# Test-only composition: one program whose single department is delegated to a
# real external coding agent through the subagent seam. The provider derives the
# child's workspace from the department session, brings its own tool stack, and
# runs on the host's own product installation and authentication; the program
# keeps the worktree, the caps, the checks, the certificate, the integration,
# the release, and both signatures.
- id: cli-mock-llm
  name: '../cli-mock-llm.ts'

# Managed child-process groups for the bash executor and for the external
# agent's own process tree.
- id: subprocess
  name: '@deepseek-ai/dsh-subprocess-local'

- id: bash
  name: '@deepseek-ai/dsh-bash-local'

- id: goal
  name: '@deepseek-ai/dsh-goal'
  config:
    defaultMaxGoalRounds: 11

- id: verification
  name: '@deepseek-ai/dsh-verification'
  config:
    maxChecks: 32
    maxTextChars: 2048

# The roster's root is absolute: the smoke runs in an isolated temporary cwd, so
# the presets beside this file are reachable only through the path the driver exports.
- id: agent-presets
  name: '@deepseek-ai/dsh-agent-presets'
  config:
    default: implementing
    roots:
      - path: !!js process.env.DSH_TEST_PROGRAM_PRESETS
        trust: system
    includeUserRoot: false

# The route every department session is created with. A delegated department
# takes no turn, so nothing is ever asked of it; the external agent's own model
# comes from that product's installation instead.
- id: agent-default-model
  name: '@deepseek-ai/dsh-agent-default-model'
  config:
    provider: cli-mock
    model: cli-mock

# Village rule: a composition that runs unattended sessions carries a session
# budget. The caps bound the department session, not the external agent's own
# spend, which this harness never sees.
- id: budget-policy
  name: '@deepseek-ai/dsh-budget-policy'
  config:
    maxTotalTokens: 5000000
    maxWallMs: 600000

- id: agent-spine
  name: '@deepseek-ai/dsh-agent-spine-demo'
  config:
    persona: 'Deliver one goal of a program on its own branch.'
    workspaceContext: false

- id: persistence
  name: '@deepseek-ai/dsh-session-persistence-jsonl'
  config:
    root: !!js process.env.DSH_TEST_SESSION_ROOT ?? './.sessions'
    compression: none

- id: checkpoint-policy
  name: '@deepseek-ai/dsh-session-checkpoint-policy'

# The two signatures the program's `requireSignoff` reads are recorded on the
# program session by the driver, through this service, before `start` opens it.
- id: signoff
  name: '@deepseek-ai/dsh-signoff'
  config:
    maxEvidence: 8
    maxEvidenceRefChars: 512

- id: subagent
  name: '@deepseek-ai/dsh-subagent'

# The provider name is fixed by the package. Its `env` stays empty: the child
# runs on the host's own product settings and authentication, which this
# composition neither supplies nor filters. What the composition does decide
# is what an unattended child may do without a prompt, since a `-p` child is
# denied everything it would have asked for: file edits, and the git commands
# the program requires of a department, because a certificate covers a commit.
- id: subagent-claude-code
  name: '@deepseek-ai/dsh-subagent-claude-code'
  config:
    permissionMode: acceptEdits
    allowedTools:
      - 'Bash(git add:*)'
      - 'Bash(git commit:*)'
      - 'Bash(git status:*)'

- id: program
  name: '@deepseek-ai/dsh-program'
  config:
    workspaceRoot: !!js process.env.DSH_TEST_PROGRAM_REPO
    requireSignoff: true
    maxConcurrentGoals: 1
    maxGoalRounds: 2
    branchPrefix: program
    evidenceMaxChars: 512
=== DRIVER:
#!/usr/bin/env node
/**
 * Test driver: create the temporary git repository the program delivers into,
 * sign its spec freeze and release, boot the delegating composition, and run one
 * one-goal program whose department is delegated to the real external coding
 * agent. The goal asks for one file the department's own check then reads, so
 * what the certificate cites is the tree the external agent left in the
 * worktree. The report, the delegation records, and the department's own
 * certificate are printed for the test to assert on.
 */

import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-agent'
import type {} from '@deepseek-ai/dsh-agent-default-model'
import { programIdFor, programSpecDigest, resolveProgramSpec } from '@deepseek-ai/dsh-program'
import type { ProgramReport, ProgramSpec } from '@deepseek-ai/dsh-program'
import { SessionId } from '@deepseek-ai/dsh-session'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type { SessionPersistence } from '@deepseek-ai/dsh-session-persistence'
import type {} from '@deepseek-ai/dsh-signoff'
import type {} from '@deepseek-ai/dsh-subagent'
import type { CheckId } from '@deepseek-ai/dsh-verification/types'

/** The artefact both of the program's signatures attest. */
const ARTEFACT = 'e'.repeat(64)

/** The file the department is asked for and certified on. */
const DELIVERABLE = 'hello.txt'

/** One department session as the e2e asserts on it. */
interface DepartmentLine {
  readonly sessionId: string
  readonly delegations: { readonly attempt: number; readonly provider: string; readonly stopReason: string }[]
  readonly certified: boolean
}

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('program driver requires a config path')

const repository = process.env.DSH_TEST_PROGRAM_REPO
if (repository === undefined) throw new Error('program driver requires DSH_TEST_PROGRAM_REPO')

// The roster's root has to be absolute and the smoke runs in an isolated
// temporary cwd, so the presets beside this file are exported by path.
process.env.DSH_TEST_PROGRAM_PRESETS = fileURLToPath(new URL('presets', import.meta.url))

// A host that configures git through `GIT_CONFIG_COUNT` hands every child a
// command-line config the shell seam cannot forward whole, and git then refuses
// every invocation. This fixture runs against its own repository, so it drops
// the whole set rather than inheriting half of it.
for (const name of Object.keys(process.env)) {
  if (name.startsWith('GIT_CONFIG_')) Reflect.deleteProperty(process.env, name)
}

/** Create the repository the program delivers into, once, with a tagged base commit. */
function ensureRepository(root: string): void {
  if (existsSync(join(root, '.git'))) return
  mkdirSync(root, { recursive: true })
  const git = (...args: string[]): void => void execFileSync('git', args, { cwd: root, stdio: 'pipe' })
  git('init', '-q', '.')
  git('config', 'user.email', 'program@example.test')
  git('config', 'user.name', 'program fixture')
  writeFileSync(join(root, 'base.txt'), 'base\n')
  git('add', 'base.txt')
  git('commit', '-qm', 'base')
  git('tag', 'base')
}

/** The program the fixture runs: one goal, delivered by the external coding agent. */
function programSpec(): ProgramSpec {
  return {
    objective: 'deliver a greeting file',
    baseRevision: 'base',
    signoff: { artefactSha256: ARTEFACT },
    implementer: { kind: 'subagent', provider: 'claude-code', label: 'external implementer' },
    goals: [{
      key: 'greeting',
      // The program certifies a branch, so the objective asks for the commit
      // as well: an uncommitted tree is refused before the checks are run.
      objective: `Add a \`${DELIVERABLE}\` containing \`hello\` at the root of this worktree, and nothing else, then commit it.`,
      preset: 'implementing',
      isolation: 'none',
      budget: { maxTotalTokens: 400_000, maxWallMs: 600_000 },
      dependsOn: [],
      checks: [{
        id: 'greeting-present' as CheckId,
        outcome: `${DELIVERABLE} at the worktree root reads hello`,
        run: `grep -qx hello ${DELIVERABLE}`,
      }],
    }],
    integration: {
      checks: [{ id: 'merged-greeting-present' as CheckId, outcome: `the merged head carries ${DELIVERABLE}`, run: `grep -qx hello ${DELIVERABLE}` }],
      gates: [],
    },
  }
}

/**
 * Record the spec-freeze and release signatures on the program session, the way
 * a client district's signer would before the program starts.
 */
async function sign(ctx: Awaited<ReturnType<typeof boot>>, spec: ProgramSpec, cwd: string): Promise<void> {
  const sessionId = SessionId(programIdFor(programSpecDigest(resolveProgramSpec(spec))))
  const signoffs = ctx.get('signoffs')
  const agents = ctx.get('agents')
  if (signoffs === undefined || agents === undefined) throw new Error('program driver requires the signoffs and agents services')
  const model = ctx.get('agentDefaultModel')?.currentSelection()
  if (model === undefined) throw new Error('program driver requires the default-model service')
  const handle = await agents.create({
    sessionId,
    meta: { cwd },
    agentOptions: { provider: model.provider, model: model.model },
  })
  try {
    for (const transition of ['spec-freeze', 'release'] as const) {
      signoffs.record(handle.agent, {
        transition,
        principal: { kind: 'human', id: 'program-fixture', displayName: 'Program Fixture' },
        artefactSha256: ARTEFACT,
        evidence: [{ kind: 'spec', ref: 'the frozen program spec' }],
      })
    }
    await ctx.sessions.flush(handle.agent.session)
  } finally {
    await handle.dispose()
  }
}

/** What each department session of this program recorded about its delegated attempts. */
async function readDepartments(persistence: SessionPersistence, report: ProgramReport): Promise<DepartmentLine[]> {
  const departmentIds = new Set(report.goals.flatMap(goal => (goal.sessionId === undefined ? [] : [goal.sessionId as string])))
  const departments: DepartmentLine[] = []
  for (const stored of await persistence.list()) {
    if (!departmentIds.has(stored.id)) continue
    const { events } = await persistence.inspect(stored.id)
    departments.push({
      sessionId: stored.id,
      delegations: events.flatMap((event: SessionEvent) => (event.type === 'program/delegation'
        ? [{ attempt: event.data.attempt, provider: event.data.provider, stopReason: event.data.stopReason }]
        : [])),
      certified: events.some((event: SessionEvent) => event.type === 'verification/certificate'),
    })
  }
  return departments
}

// The repository has to exist before the program plugin validates its
// workspaceRoot, so it is minted before the composition loads.
ensureRepository(repository)

const ctx = await boot('program-claude-implementer-e2e', resolveConfigPath(configPath, undefined))
try {
  await ctx.get('loader')?.await()
  const programs = ctx.get('programs')
  const persistence = ctx.get('sessionPersistence')
  if (programs === undefined || persistence === undefined) throw new Error('program driver requires the programs and session persistence services')
  const spec = programSpec()
  await sign(ctx, spec, repository)
  const report = await programs.start(spec)
  process.stdout.write(`${JSON.stringify({
    type: 'result',
    providers: ctx.get('subagents')?.list() ?? [],
    report,
    departments: await readDepartments(persistence, report),
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}

#!/usr/bin/env node
/**
 * Self-assessment through the program workflow: one department, on the
 * operator's Claude Code route, reads the evidence dossier committed in the
 * repository and writes `assessment.md` on its own branch; the goal is certified
 * by the mechanical verifier committed beside the evidence, the integration
 * re-runs it on the merged head, and the program ledger is printed as the
 * durable record. Adapted from the program fixture's driver.
 */

import { existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-agent'
import type {} from '@deepseek-ai/dsh-agent-default-model'
import { programIdFor, programSpecDigest, resolveProgramSpec } from '@deepseek-ai/dsh-program'
import type { ProgramSpec } from '@deepseek-ai/dsh-program'
import type {} from '@deepseek-ai/dsh-program'
import { SessionId } from '@deepseek-ai/dsh-session'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type { SessionPersistence } from '@deepseek-ai/dsh-session-persistence'
import type {} from '@deepseek-ai/dsh-signoff'
import type { CheckId } from '@deepseek-ai/dsh-verification/types'

/** The artefact both of the program's signatures attest: the dossier's question. */
const ARTEFACT = 'a'.repeat(64)

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('self-assessment driver requires a config path')
const repository = process.env.DSH_TEST_PROGRAM_REPO
if (repository === undefined || !existsSync(`${repository}/.git`)) throw new Error('self-assessment driver requires DSH_TEST_PROGRAM_REPO to name an initialised repository')

process.env.DSH_TEST_PROGRAM_PRESETS = fileURLToPath(new URL('presets', import.meta.url))
for (const name of Object.keys(process.env)) {
  if (name.startsWith('GIT_CONFIG_')) Reflect.deleteProperty(process.env, name)
}

const VERIFY = 'node checks/verify-assessment.mjs assessment.md'

const BRIEF = [
  'Write `assessment.md` at the root of this repository: an honest assessment of whether the project described by the files under `evidence/` is viable and whether any part of it is state of the art.',
  'Read `evidence/goals-and-question.md` first; it states the four goals, the two questions, and the rules. Then read the primary records before the summaries: `evidence/proving-ground-README.md`, `evidence/census.txt`, `evidence/records-index.txt`, `evidence/commits-last-30h.txt`; then the notes.',
  'The document has exactly these level-two sections, in this order: `## Verdict`, `## Evidence`, `## What the evidence does not support`, `## What would change the verdict`.',
  '`## Verdict` opens with two lines, each on its own line and exactly in this form: `Viable: yes|no|undetermined (high|medium|low confidence)` and `State of the art: yes|no|in part|undetermined (high|medium|low confidence)`, followed by one paragraph for each that names the part of the project the verdict rests on.',
  '`## Evidence` is a list of at least eight bullets; every bullet states one fact and ends with the file it comes from as `(evidence/<file>)`; cite at least six distinct files; a measured result is reported with its numbers, its verdict, and its caveats exactly as the record states them.',
  '`## What the evidence does not support` lists at least three claims a reader might expect that the evidence does not carry, including any claim the project\'s own summaries make that the records do not.',
  '`## What would change the verdict` lists at least three measurable conditions.',
  'Between 600 and 2500 words. No placeholders. Verify with `node checks/verify-assessment.mjs assessment.md` before you stop; the validator runs the same command.',
].join(' ')

/** One goal: the assessment, certified by the committed verifier. */
function programSpec(): ProgramSpec {
  return {
    objective: 'assess whether this project is viable and state of the art, from its own evidence',
    baseRevision: 'base',
    signoff: { artefactSha256: ARTEFACT },
    goals: [
      {
        key: 'assessment',
        objective: BRIEF,
        preset: 'implementing',
        isolation: 'none',
        budget: { maxTotalTokens: 2_000_000, maxWallMs: 1_500_000 },
        dependsOn: [],
        checks: [{ id: 'assessment-verified' as CheckId, outcome: 'assessment.md exists and passes the committed verifier', run: VERIFY }],
      },
    ],
    integration: {
      checks: [{ id: 'merged-assessment-verified' as CheckId, outcome: 'the merged head carries a verified assessment', run: VERIFY }],
      gates: ['test -r assessment.md'],
    },
  }
}

interface LedgerLine { readonly sessionId: string; readonly events: { readonly type: string; readonly data: unknown }[]; readonly signoffs: string[] }
interface MemberLine { readonly sessionId: string; readonly programId: string; readonly key: string; readonly certified: boolean; readonly caps: unknown }

async function readRoot(persistence: SessionPersistence): Promise<{ ledgers: LedgerLine[]; members: MemberLine[] }> {
  const ledgers: LedgerLine[] = []
  const members: MemberLine[] = []
  for (const stored of await persistence.list()) {
    const { events } = await persistence.inspect(stored.id)
    const programEvents = events.filter((event: SessionEvent) => event.type.startsWith('program/') && event.type !== 'program/member')
    if (programEvents.length > 0) {
      ledgers.push({
        sessionId: stored.id,
        events: programEvents.map(event => ({ type: event.type, data: event.data })),
        signoffs: events.flatMap(event => (event.type === 'signoff/recorded' ? [event.data.transition] : [])),
      })
    }
    for (const event of events) {
      if (event.type !== 'program/member') continue
      members.push({
        sessionId: stored.id,
        programId: event.data.programId,
        key: event.data.key,
        certified: events.some(candidate => candidate.type === 'verification/certificate'),
        caps: events.find(candidate => candidate.type === 'budget/caps')?.data,
      })
    }
  }
  return { ledgers, members }
}

async function sign(ctx: Awaited<ReturnType<typeof boot>>, spec: ProgramSpec, cwd: string): Promise<void> {
  const sessionId = SessionId(programIdFor(programSpecDigest(resolveProgramSpec(spec))))
  const signoffs = ctx.get('signoffs')
  const agents = ctx.get('agents')
  if (signoffs === undefined || agents === undefined) throw new Error('self-assessment driver requires the signoffs and agents services')
  if ((await ctx.get('sessionPersistence')?.list() ?? []).some(stored => stored.id === sessionId)) return
  const model = ctx.get('agentDefaultModel')?.currentSelection()
  if (model === undefined) throw new Error('self-assessment driver requires the default-model service')
  const handle = await agents.create({ sessionId, meta: { cwd }, agentOptions: { provider: model.provider, model: model.model } })
  try {
    for (const transition of ['spec-freeze', 'release'] as const) {
      signoffs.record(handle.agent, {
        transition,
        principal: { kind: 'human', id: 'lab-lead', displayName: 'Lab lead' },
        artefactSha256: ARTEFACT,
        evidence: [{ kind: 'spec', ref: 'the frozen self-assessment spec' }],
      })
    }
    await ctx.sessions.flush(handle.agent.session)
  } finally {
    await handle.dispose()
  }
}

const ctx = await boot('self-assessment', resolveConfigPath(configPath, undefined))
try {
  await ctx.get('loader')?.await()
  const programs = ctx.get('programs')
  const persistence = ctx.get('sessionPersistence')
  if (programs === undefined || persistence === undefined) throw new Error('self-assessment driver requires the programs and session persistence services')
  const spec = programSpec()
  await sign(ctx, spec, repository)
  const report = await programs.start(spec)
  const observed = await readRoot(persistence)
  process.stdout.write(`${JSON.stringify({ type: 'result', report, ...observed })}\n`)
} finally {
  await ctx.fiber.dispose()
}

#!/usr/bin/env node
// Mechanical verifier for assessment.md: structure, verdict lines, citations
// that resolve to files under evidence/, and bounds. Exit 0 when every rule
// holds; otherwise print each failure and exit 1.
import { existsSync, readFileSync } from 'node:fs'
import { join, dirname } from 'node:path'

const path = process.argv[2] ?? 'assessment.md'
const failures = []
if (!existsSync(path)) {
  console.error(`missing ${path}`)
  process.exit(1)
}
const text = readFileSync(path, 'utf8')
const root = dirname(path) === '.' ? process.cwd() : dirname(path)
const sections = ['## Verdict', '## Evidence', '## What the evidence does not support', '## What would change the verdict']
const positions = sections.map(s => text.indexOf(`\n${s}\n`) === -1 && !text.startsWith(`${s}\n`) ? -1 : (text.startsWith(`${s}\n`) ? 0 : text.indexOf(`\n${s}\n`)))
sections.forEach((s, i) => { if (positions[i] === -1) failures.push(`section missing: ${s}`) })
for (let i = 1; i < positions.length; i++) {
  if (positions[i] !== -1 && positions[i - 1] !== -1 && positions[i] < positions[i - 1]) failures.push(`section out of order: ${sections[i]}`)
}
const body = (name) => {
  const i = sections.indexOf(name)
  if (positions[i] === -1) return ''
  const start = positions[i] + name.length + 1
  const next = positions.slice(i + 1).filter(p => p !== -1).sort((a, b) => a - b)[0]
  return text.slice(start, next === undefined ? text.length : next)
}
const verdict = body('## Verdict')
if (!/^Viable: (yes|no|undetermined) \((high|medium|low) confidence\)/m.test(verdict)) failures.push('verdict line missing: "Viable: yes|no|undetermined (high|medium|low confidence)"')
if (!/^State of the art: (yes|no|in part|undetermined) \((high|medium|low) confidence\)/m.test(verdict)) failures.push('verdict line missing: "State of the art: yes|no|in part|undetermined (high|medium|low confidence)"')
const bullets = (s) => s.split('\n').filter(l => /^\s*[-*] /.test(l))
const evidenceBullets = bullets(body('## Evidence'))
if (evidenceBullets.length < 8) failures.push(`evidence needs at least 8 bullets, found ${evidenceBullets.length}`)
const cited = new Set()
for (const line of evidenceBullets) {
  const refs = [...line.matchAll(/evidence\/([A-Za-z0-9._-]+)/g)].map(m => m[1])
  if (refs.length === 0) failures.push(`evidence bullet without a citation: ${line.trim().slice(0, 80)}`)
  for (const ref of refs) {
    if (!existsSync(join(root, 'evidence', ref))) failures.push(`citation does not resolve: evidence/${ref}`)
    else cited.add(ref)
  }
}
if (cited.size < 6) failures.push(`at least 6 distinct evidence files must be cited, found ${cited.size}`)
if (bullets(body('## What the evidence does not support')).length < 3) failures.push('"What the evidence does not support" needs at least 3 bullets')
if (bullets(body('## What would change the verdict')).length < 3) failures.push('"What would change the verdict" needs at least 3 bullets')
const words = text.split(/\s+/).filter(Boolean).length
if (words < 600 || words > 2500) failures.push(`length must be 600 to 2500 words, found ${words}`)
if (/TODO|TBD|lorem/i.test(text)) failures.push('placeholder text present')
if (failures.length > 0) {
  for (const f of failures) console.error(`FAIL ${f}`)
  process.exit(1)
}
console.log(`ok: ${evidenceBullets.length} evidence bullets, ${cited.size} files cited, ${words} words`)
=== goals-and-question:
# The question, the goals, and the rules of this assessment

You are assessing an open-source project, DeepSeek Harness as built by the Daliesk lab, from the evidence in this directory only. The evidence is the project's own records: run records and their README, Agent Notes, a census of what cells reached outside their workspace, the commit log of the last thirty hours, and a comparison with two external systems. Some files are the project's own summaries of itself (`results-draft.md`, `roles-matrix.md`); prefer the primary records (`proving-ground-README.md`, `census.txt`, `records-index.txt`, `commits-last-30h.txt`) whenever a summary and a record could disagree.

## The project's stated goals

1. The best harness: a plugin-based agent harness that makes any LLM the best agentic coder it can be.
2. The best agentic software creation through that harness.
3. A roughly 120B-parameter open-weight model trained with reinforcement learning from verifiable rewards on the harness's certified runs.
4. A loop in which the harness improves itself: frozen paired experiments whose verdicts promote or reject changes.

## The two questions

- **Viable**: given the evidence, can this project reach its stated goals with the means the evidence shows (one operator's subscription, agents as the workforce, the bench and district as instruments)? Answer `yes`, `no`, or `undetermined`, with a confidence.
- **State of the art**: given the evidence, is any part of this project ahead of the field the evidence describes (the competitive baselines, the ruflo comparison, the hypothesis slate's summary of the quarter's results)? Answer `yes`, `no`, `in part`, or `undetermined`, with a confidence, and name the part.

## Rules

- Every claim in the evidence section cites the file it comes from, as `(evidence/<file>)`. A claim without a citation is not evidence.
- Distinguish what was measured from what was built, and what was built from what was planned.
- A refutation counts as much as a confirmation. An inconclusive verdict is reported as inconclusive, never rounded toward either side.
- Where the project's own summary makes a claim the records do not carry, say so.
- Write for a reader who will act on the verdict: name what would change it.

#!/usr/bin/env node
// Records one Proving Ground run under data/proving-ground/<name>/: copies the
// driver's exports and every cell and shift session log out of the directory
// the driver ran in, and writes a manifest with the repository head, the
// composition, the implementer, the session ids, and every file's SHA-256.
// Node built-ins only.
//
// Usage: node record-run.mjs <run-directory> <name> --composition <path> [--elapsed-seconds <n>] [--partial <reason>]
//
//   <run-directory>   where the driver ran: holds facts.jsonl, trajectories.jsonl,
//                     observatory.json, observatory.html, .sessions/, and either
//                     stdout.jsonl (a fleet driver's result line) or status.json
//                     (a shift driver's status)
//   <name>            the run directory name, e.g. 2026-09-06-claude-code-run-2
//   --composition     repository-relative cordis.yml the driver booted
//   --elapsed-seconds wall time of the run when the driver did not record it
//   --partial         record a run whose driver died before writing its result:
//                     the session logs are kept, result.json states only
//                     `{ type: 'partial', reason }`, and the manifest carries the
//                     reason, so the cells that ran stay evidence without a
//                     verdict the driver never computed
//
// The run directory is written once; an existing target is refused so a
// recorded run is never rewritten in place. Recording prints the escape census
// of the new record (`census-escapes.mjs`), so what each cell reached outside
// its own workspace is read at the moment the run enters the corpus.

import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
