/** Exit code the kill switch leaves behind, distinct from every clean exit. */
const KILLED = 9

/** The artefact both of the program's signatures attest. */
const ARTEFACT = 'f'.repeat(64)

/** One program session's ledger as the e2e asserts on it. */
interface LedgerLine {
  readonly sessionId: string
  readonly events: { readonly type: string; readonly data: unknown }[]
  /** Transitions the same session was signed for, in log order. */
  readonly signoffs: string[]
}

/** One refusal the read barrier recorded, as the e2e asserts on it. */
interface DenialLine {
  /** The session that was refused the read. */
  readonly sessionId: string
  /** The seam that refused it. */
  readonly capability: string
  /** The path as the refused tool call named it. */
  readonly displayPath: string
}

/** One member session's stamp as the e2e asserts on it. */
interface MemberLine {
  readonly sessionId: string
  readonly programId: string
  readonly key: string
  /** Whether the member's own log carries a certificate. */
  readonly certified: boolean
  /** The caps the member session recorded for itself. */
  readonly caps: unknown
}

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('program driver requires a config path')

const repository = process.env.DSH_TEST_PROGRAM_REPO
if (repository === undefined) throw new Error('program driver requires DSH_TEST_PROGRAM_REPO')

// The roster's root has to be absolute and the smoke runs in an isolated
// temporary cwd, so the presets beside this file are exported by path.
process.env.DSH_TEST_PROGRAM_PRESETS = fileURLToPath(new URL('presets', import.meta.url))

// A host that configures git through `GIT_CONFIG_COUNT` hands every child a
// command-line config the shell seam cannot forward whole: `GIT_CONFIG_KEY_*`
// is credential-shaped, so the scrub drops the keys and keeps the count, and
// git then refuses every invocation. The fixture runs against its own
// repository, so it drops the whole set rather than inheriting half of it.
for (const name of Object.keys(process.env)) {
  if (name.startsWith('GIT_CONFIG_')) Reflect.deleteProperty(process.env, name)
}

/** Create the repository the program delivers into, once, with a tagged base commit. */
function ensureRepository(root: string): void {
  if (existsSync(join(root, '.git'))) return
  mkdirSync(root, { recursive: true })
  const git = (...args: string[]): void => void execFileSync('git', args, { cwd: root, stdio: 'pipe' })
  git('init', '-q', '.')
  git('config', 'user.email', 'program@example.test')
  git('config', 'user.name', 'program fixture')
  writeFileSync(join(root, 'base.txt'), 'base\n')
  git('add', 'base.txt')
  git('commit', '-qm', 'base')
  git('tag', 'base')
}

/**
 * The program the fixture runs: two goals, the second delivered after the
 * first. Each goal names the file its department writes, which is what the
 * mock implementer writes and then commits, and the integration standard
 * measures a file only the integration's own repair turn can create.
 */
function programSpec(label: string): ProgramSpec {
  const budget = { maxTotalTokens: 400_000, maxWallMs: 300_000 }
  return {
    objective: `deliver the ${label} release`,
    baseRevision: 'base',
    signoff: { artefactSha256: ARTEFACT },
    goals: [
      {
        key: 'api',
        objective: 'Deliver the api of this program on its own branch. Write api.md and commit it.',
        preset: 'implementing',
        isolation: 'none',
        budget,
        dependsOn: [],
        checks: [{ id: 'api-present' as CheckId, outcome: 'the branch carries the api file', run: 'test -f api.md' }],
      },
      {
        key: 'docs',
        objective: 'Document the api of this program on its own branch. Write docs.md and commit it.',
        preset: 'documenting',
        isolation: 'none',
        budget,
        dependsOn: ['api'],
        checks: [{ id: 'docs-present' as CheckId, outcome: 'the branch carries the docs file', run: 'test -f docs.md' }],
      },
    ],
    integration: {
      checks: [{ id: 'merged-base-present' as CheckId, outcome: 'the merged head carries the base file', run: 'test -f base.txt' }],
      // The merge alone never satisfies this gate: no department branch carries
      // the file, so the merged head is what the integration's own turn repairs.
      gates: ['test -f integrated.md'],
    },
  }
}

/** Every program ledger and every member stamp in the persistence root. */
async function readRoot(persistence: SessionPersistence): Promise<{ ledgers: LedgerLine[]; members: MemberLine[] }> {
  const ledgers: LedgerLine[] = []
  const members: MemberLine[] = []
  for (const stored of await persistence.list()) {
    const { events } = await persistence.inspect(stored.id)
    const programEvents = events.filter((event: SessionEvent) => event.type.startsWith('program/') && event.type !== 'program/member')
    if (programEvents.length > 0) {
      ledgers.push({
        sessionId: stored.id,
        events: programEvents.map(event => ({ type: event.type, data: event.data })),
        signoffs: events.flatMap(event => (event.type === 'signoff/recorded' ? [event.data.transition] : [])),
      })
    }
    for (const event of events) {
      if (event.type !== 'program/member') continue
      members.push({
        sessionId: stored.id,
        programId: event.data.programId,
        key: event.data.key,
        certified: events.some(candidate => candidate.type === 'verification/certificate'),
        caps: events.find(candidate => candidate.type === 'budget/caps')?.data,
      })
    }
  }
  return { ledgers, members }
}

/**
 * Record the spec-freeze and release signatures on the program session, the way
 * a client district's signer would before the program starts. A session that
 * already carries them is left alone, so a resumed phase signs nothing twice.
 */
async function sign(ctx: Awaited<ReturnType<typeof boot>>, spec: ProgramSpec, cwd: string): Promise<void> {
  const sessionId = SessionId(programIdFor(programSpecDigest(resolveProgramSpec(spec))))
  const signoffs = ctx.get('signoffs')
  const agents = ctx.get('agents')
  if (signoffs === undefined || agents === undefined) throw new Error('program driver requires the signoffs and agents services')
  if ((await ctx.get('sessionPersistence')?.list() ?? []).some(stored => stored.id === sessionId)) return
  const model = ctx.get('agentDefaultModel')?.currentSelection()
  if (model === undefined) throw new Error('program driver requires the default-model service')
  const handle = await agents.create({
    sessionId,
    meta: { cwd },
    agentOptions: { provider: model.provider, model: model.model },
  })
  try {
    for (const transition of ['spec-freeze', 'release'] as const) {
      signoffs.record(handle.agent, {
        transition,
        principal: { kind: 'human', id: 'program-fixture', displayName: 'Program Fixture' },
        artefactSha256: ARTEFACT,
        evidence: [{ kind: 'spec', ref: 'the frozen program spec' }],
      })
    }
    await ctx.sessions.flush(handle.agent.session)
  } finally {
    await handle.dispose()
  }
}

// The repository has to exist before the program plugin validates its
// workspaceRoot, so it is minted before the composition loads.
ensureRepository(repository)

const ctx = await boot('program-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the program mounts presets and reads
  // persisted sessions, so the driver drives only the settled application.
  await ctx.get('loader')?.await()
  const programs = ctx.get('programs')
  const persistence = ctx.get('sessionPersistence')
  if (programs === undefined || persistence === undefined) throw new Error('program driver requires the programs and session persistence services')
  if (process.env.DSH_TEST_PROGRAM_KILL_AFTER_CERTIFIED === '1') {
    ctx.on('session/event', (_session, event) => {
      if (event.type === 'program/goal' && event.data.status === 'certified') process.exit(KILLED)
    })
  }
  if (process.env.DSH_TEST_PROGRAM_KILL_AFTER_INTEGRATION_RUN === '1') {
    // The directive follows the flushed run of the integration's first attempt,
    // so the exit leaves persistence holding an integration session with a goal,
    // a standard, and one recorded run — the state a resume takes back over.
    ctx.on('session/event', (session, event) => {
      if (event.type === 'verification/directive' && session.id.endsWith(INTEGRATION_KEY)) process.exit(KILLED)
    })
  }
  const denials: DenialLine[] = []
  ctx.on('session/event', (session, event) => {
    if (event.type === 'read-barrier/denied') {
      denials.push({ sessionId: session.id, capability: event.data.capability, displayPath: event.data.displayPath })
    }
  }, { global: true })
  const spec = programSpec(process.env.DSH_TEST_PROGRAM_LABEL ?? 'first')
  // The program id is the spec digest, so the two signatures the deployment
  // requires are recorded on that session before the program opens it. A second
  // phase resuming the same root finds them already there.
  await sign(ctx, spec, repository)
  const report = await programs.start(spec)
  const observed = await readRoot(persistence)
  process.stdout.write(`${JSON.stringify({ type: 'result', report, denials, ...observed })}\n`)
} finally {
  await ctx.fiber.dispose()
}

/**
 * Keyless adapter that plays every session of one program: a department that
 * writes before it commits, and an integration that probes a department's
 * worktree before it repairs the merged head.
 *
 * A department's first turn writes the file its goal names and commits nothing,
 * which is the state a department must not be certified in; the turn that
 * follows the program's `<uncommitted_work>` directive commits it. The
 * integration takes a turn only when the merged head fails its standard: it
 * reads a department worktree through the `read` tool, which is where the read
 * barrier records a refusal, and then creates and commits the file the failing
 * gate measures.
 *
 * The markers below are pinned by the e2e and by the fixture's spec, so keep
 * them and its check commands together.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

/** The turn text the program delivers when a worktree carries uncommitted work. */
const UNCOMMITTED_MARKER = '<uncommitted_work>'

/** The turn text the program delivers when a standard did not pass. */
const CHECKS_FAILED_MARKER = '<checks_failed>'

/** The file the integration creates and commits, which its own standard measures. */
const INTEGRATED_FILE = 'integrated.md'

/** The department worktree file the integration tries to read, relative to its own worktree. */
const DEPARTMENT_FILE = '../api/api.md'

/** A file of the integration's own worktree, which the barrier grants it beneath the denied root. */
const OWN_FILE = 'base.txt'

/** Where in one session's turn the adapter is: the turn's text and the tool results it already has. */
interface Position {
  /** Text of the newest turn the session was handed, empty for a session that was handed none. */
  readonly text: string
  /** Tool results delivered since that turn, which is the step this stream serves. */
  readonly results: number
}

/**
 * Read the newest turn and the steps already taken in it.
 * @param options - the request the loop assembled.
 * @returns the turn text and the tool results that followed it.
 */
function position(options: GenerateOptions): Position {
  let results = 0
  for (let index = options.messages.length - 1; index >= 0; index -= 1) {
    const message = options.messages[index]
    if (message === undefined || message.role !== 'user') continue
    const content = message.content ?? []
    if (content.some(block => block.type === 'tool-result')) {
      results += 1
      continue
    }
    return { text: content.filter(block => block.type === 'text').map(block => block.text).join(''), results }
  }
  return { text: '', results }
}

/**
 * The file one department's goal told it to write.
 * @param options - the request whose history carries the goal text.
 * @returns the file name, or `undefined` for a session that was never given one.
 */
function departmentFile(options: GenerateOptions): string | undefined {
  const history = options.messages
    .flatMap(message => message.content ?? [])
    .flatMap(block => (block.type === 'text' ? [block.text] : []))
    .join('\n')
  return /Write ([a-z0-9-]+\.md)/.exec(history)?.[1]
}

class ProgramAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const { text, results } = position(options)
    if (text.includes(CHECKS_FAILED_MARKER)) {
      // The integration probes the department worktree, which the barrier
      // refuses, then its own, which the barrier grants beneath the same denied
      // root, and only then repairs the merged head.
      if (results === 0) {
        yield * call('integration-probe', 'read', { file_path: DEPARTMENT_FILE })
        return
      }
      if (results === 1) {
        yield * call('integration-own-read', 'read', { file_path: OWN_FILE })
        return
      }
      if (results === 2) {
        yield * call('integration-repair', 'bash', {
          command: `printf 'merged\\n' > ${INTEGRATED_FILE} && git add -A && git commit -qm 'integrate the departments'`,
          description: 'Create and commit the file the integration standard measures.',
        })
        return
      }
      yield * reply('TURN COMPLETE')
      return
    }
    if (results > 0) {
      // A department's turn is one tool call, then the answer that ends it.
      yield * reply('TURN COMPLETE')
      return
    }
    const file = departmentFile(options) ?? INTEGRATED_FILE
    if (text.includes(UNCOMMITTED_MARKER)) {
      yield * call('department-commit', 'bash', {
        command: `git add -A && git commit -qm 'deliver ${file}'`,
        description: 'Commit what this goal delivers.',
      })
      return
    }
    yield * call('department-write', 'bash', {
      command: `printf 'delivered\\n' > ${file}`,
      description: 'Write what this goal delivers.',
    })
  }
}

/** One tool call as the canonical block sequence of a step that stops on tool calls. */
function * call(id: string, name: string, args: object): Generator<StreamChunk> {
  const serialized = JSON.stringify(args)
  yield { type: 'block-start', index: 0, blockType: 'tool-call' }
  yield { type: 'tool-call-delta', index: 0, id: CallId(id), name, argumentsDelta: serialized }
  yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId(id), name, arguments: serialized } }
  yield { type: 'usage', usage: { inputTokens: 17, outputTokens: 5 } }
  yield { type: 'finish', reason: { kind: 'tool-calls' } }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 13, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

