    // the integration recorded its first run over the merged head.
    await phase(sessions, repository, {
      DSH_TEST_PROGRAM_LABEL: INTEGRATION_LABEL,
      DSH_TEST_PROGRAM_KILL_AFTER_INTEGRATION_RUN: '1',
