// Boot one csv-tools composition and print the mounted LLM providers, without
// starting a program: proof that the overlay composes.
import { fileURLToPath } from 'node:url'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type {} from '@deepseek-ai/dsh-agent-default-model'
import type {} from '@deepseek-ai/dsh-program'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('needs a config path')
process.env.DSH_TEST_PROGRAM_PRESETS = fileURLToPath(
  new URL('presets', `file://${process.env.DSH_CSV_FIXTURE}/`),
)
for (const name of Object.keys(process.env)) {
  if (name.startsWith('GIT_CONFIG_')) Reflect.deleteProperty(process.env, name)
}
const ctx = await boot('csv-tools-overlay-check', resolveConfigPath(configPath, undefined))
try {
  await ctx.get('loader')?.await()
  console.log('default model:', JSON.stringify(ctx.get('agentDefaultModel')?.currentSelection()))
  console.log('programs service:', ctx.get('programs') !== undefined)
} finally {
  await ctx.fiber.dispose()
}

